package com.probestack.forgesphere.config;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

import io.swagger.v3.oas.models.OpenAPI;
import io.swagger.v3.oas.models.info.Info;
import io.swagger.v3.oas.models.info.Contact;
import io.swagger.v3.oas.models.info.License;
import io.swagger.v3.oas.models.Components;
import io.swagger.v3.oas.models.security.SecurityScheme;

@Configuration
public class SpringDocConfiguration {

    @Bean(name = "com.probestack.forgesphere.config.SpringDocConfiguration.apiInfo")
    OpenAPI apiInfo() {
        return new OpenAPI()
                .info(
                        new Info()
                                .title("Probestack Compliance Service API")
                                .description("API specification for probestack-compliance-service.  This service manages governance compliance rules and supports compliance scanning for microservices, Apigee proxies, and Kong resources.  ## Microservice  Microservice Name: probestack-compliance-service  ## MongoDB Collections  ### governance_compliance_rules  Stores compliance rule definitions used by the UI and scan engine.  Primary Fields: - ruleId: Unique rule identifier generated by Java service. Example: CR13 - ruleName: Compliance rule display name - ruleDescription: Detailed rule description - ruleType: PRE_DEFINED or CUSTOM - ruleOwner: Owner team or person - category: DOCUMENTATION, LOGGING, SECURITY, PERFORMANCE, HEALTH, GENERAL - severity: REQUIRED, MANDATORY, RECOMMENDED, OPTIONAL - enabled: Whether the rule is enabled - mandatory: Whether the rule is mandatory - displayOrder: UI display order - icon: UI icon name - status: complaint or non-compliant - createDate: Created timestamp - createdBy: User who created the rule - updatedDate: Last updated timestamp - updatedBy: User who last updated the rule  Recommended Indexes: - Unique index on ruleId - Compound index on status, category, ruleType  ### governance_compliance_scans  Stores submitted, completed, and failed compliance scan executions.  Primary Fields: - scanId: Unique scan identifier generated by Java service - projectName: Project name - companyName: Company name - assetId: Asset identifier - assetName: Microservice, proxy, or resource name - assetType: MICROSERVICE, APIGEE, KONG - sourceType: GITHUB, GITLAB, BITBUCKET, ZIP_UPLOAD, BUNDLE_UPLOAD - source: Repository or uploaded bundle details - rules: Rule selection details - scanOptions: Scan execution options - status: submitted, completed, error - compliance: PENDING, COMPLIANT, NON_COMPLIANT, PARTIAL - scanResults: Rule-level scan results - scanDate: Actual scan completion date - createDate: Created timestamp - createdBy: User who submitted the scan - updatedDate: Last updated timestamp - updatedBy: User or scheduler that last updated the record  Recommended Indexes: - Unique index on scanId - Compound index on status, createDate - Compound index on projectName, assetType, assetName  ## Scheduler  Scheduler Task: ComplianceScanScheduler is also inside the probestack-compliance-service.  Frequency: Every 5 minutes  Processing Flow: 1. Fetch records from governance_compliance_scans where status = submitted. 2. Process records one by one. 3. Fetch selected compliance rules. 4. Fetch source code or proxy bundle. 5. Scan the source against selected rules. 6. Store scan results in the governance_compliance_scans collection 7. Update status to completed or error. ")
                                .version("1.0.0")
                )
        ;
    }
}